require_once dirname(__DIR__) . '/_common.php';if(!osis_admin_is_post()){http_response_code(405);exit('Metode tidak diizinkan.');}osis_verify_csrf();$id=isset($_POST['id'])?(int)$_POST['id']:0;$stmt=$pdo->prepare('SELECT judul FROM galeri_album WHERE id=?');$stmt->execute([$id]);$album=$stmt->fetch();if($album){$stmt=$pdo->prepare('SELECT file FROM galeri_foto WHERE album_id=?');$stmt->execute([$id]);$files=$stmt->fetchAll();$pdo->prepare('DELETE FROM galeri_album WHERE id=?')->execute([$id]);foreach($files as $file)osis_delete_uploaded_file($file['file']);osis_log_activity('Menghapus album galeri: '.$album['judul']);osis_set_flash('success','Album dan seluruh foto di dalamnya berhasil dihapus.');}else{osis_set_flash('error','Album tidak ditemukan.');}osis_redirect('admin/galeri/index.php');
